export type PrecalculatedPreset = {
  bodyIds: string[]
  x: number[][]
  y: number[][]
}

function zip(id: string, xs: number[], ys: number[]): [string, { x: number; y: number }[]] {
  const frames: { x: number; y: number }[] = []
  for (let i = 0; i < xs.length; i++) {
    frames.push({ x: xs[i]!, y: ys[i]! })
  }
  return [id, frames]
}

